package model

import (
	"crypto/tls"
	"strconv"

	"gitlab.com/piccolo_su/vegeta/pkg/flag"
	"gitlab.com/piccolo_su/vegeta/pkg/logging"
	"gopkg.in/gomail.v2"
)

func SendMails(mailTo []string, subject string, body string, emailOpts *flag.EmailOpts) error {

	mailConn := map[string]string{
		"user": emailOpts.Username,
		"pass": emailOpts.Password,
		"host": emailOpts.Host,
		"port": emailOpts.Port,
	}

	port, _ := strconv.Atoi(mailConn["port"])

	m := gomail.NewMessage()

	m.SetHeader("From", m.FormatAddress(mailConn["user"], "探真官方"))
	m.SetHeader("To", mailTo...)
	m.SetHeader("Subject", subject)
	m.SetBody("text/html", body)

	d := gomail.NewDialer(mailConn["host"], port, mailConn["user"], mailConn["pass"])
	tl := tls.Config{InsecureSkipVerify: true}
	d.TLSConfig = &tl

	err := d.DialAndSend(m)
	return err

}

